import { describe, expect, it } from "vitest";
import {
  APEX_PRESETS,
  ApexGenerationError,
  apexClassName,
  apexPropertyName,
  generateApexClasses,
  isApexReservedWord,
} from "../index";
import { isApexSystemTypeName, uniqueApexName } from "../naming";

const HEADER = [
  "// Generated by SyntaxFiddle — JSON to Apex Class Generator",
  "// https://syntaxfiddle.com/json-to-apex/",
  "",
];

/** Builds the expected full .cls text (header + lines + trailing newline). */
function expectCls(lines: string[]): string {
  return [...HEADER, ...lines, ""].join("\n");
}

describe("apex naming", () => {
  it("preserves original JSON keys that are valid, unreserved identifiers", () => {
    expect(apexPropertyName("totalSize")).toBe("totalSize");
    expect(apexPropertyName("AnnualRevenue")).toBe("AnnualRevenue");
    expect(apexPropertyName("Id")).toBe("Id");
    expect(apexPropertyName("foo_bar")).toBe("foo_bar");
    expect(apexPropertyName("__c")).toBe("__c");
  });

  it("mangles reserved words with an X suffix, but never legal member names", () => {
    expect(isApexReservedWord("class")).toBe(true);
    expect(isApexReservedWord("Class")).toBe(true);
    expect(isApexSystemTypeName("date")).toBe(true);
    // Official Apex keywords — must mangle to compile.
    expect(apexPropertyName("class")).toBe("ClassX");
    expect(apexPropertyName("trigger")).toBe("TriggerX");
    expect(apexPropertyName("select")).toBe("SelectX");
    expect(apexPropertyName("int")).toBe("IntX");
    expect(apexPropertyName("type")).toBe("TypeX");
    // System class names are legal member names — preserved so the JSON
    // key still deserializes (shadowing a system class is legal Apex).
    expect(apexPropertyName("Date")).toBe("Date");
    expect(apexPropertyName("Test")).toBe("Test");
    expect(apexPropertyName("url")).toBe("url");
    // `id` is deliberately NOT treated as a conflict at all.
    expect(apexPropertyName("id")).toBe("id");
  });

  it("produces valid identifiers for unsafe keys", () => {
    expect(apexPropertyName("")).toBe("Field");
    expect(apexPropertyName("123")).toBe("Field123");
    expect(apexPropertyName("!!!")).toBe("Field");
    expect(apexClassName("my wrapper class")).toBe("MyWrapperClass");
    expect(apexClassName("replicas")).toBe("Replicas");
  });

  it("resolves member-name collisions with numeric suffixes, case-insensitively", () => {
    expect(uniqueApexName("Foo", new Set())).toBe("Foo");
    const used = new Set(["Foo".toLowerCase()]);
    expect(uniqueApexName("Foo", used)).toBe("Foo2");
    expect(uniqueApexName("Foo", used)).toBe("Foo3");
    // Apex identifiers are case-insensitive: `id` and `Id` cannot coexist.
    const caseUsed = new Set(["id"]);
    expect(uniqueApexName("Id", caseUsed)).toBe("Id2");
  });

  it("emits distinct members when JSON keys differ only by case", () => {
    const result = generateApexClasses(
      JSON.stringify({ id: 1, Id: 2 }),
    );
    expect(result.apex).toContain("public Decimal id { get; set; }");
    expect(result.apex).toContain("public Decimal Id2 { get; set; }");
  });
});

describe("apex type mapping", () => {
  it("maps every JSON number to Decimal", () => {
    const { apex } = generateApexClasses(
      JSON.stringify({
        whole: 42,
        fraction: 3.14,
        huge: 9007199254740993,
        scientific: 1e21,
      }),
    );
    expect(apex).toContain("public Decimal whole { get; set; }");
    expect(apex).toContain("public Decimal fraction { get; set; }");
    expect(apex).toContain("public Decimal huge { get; set; }");
    expect(apex).toContain("public Decimal scientific { get; set; }");
    expect(apex).not.toContain("Integer");
    expect(apex).not.toContain("Long ");
  });

  it("maps ISO 8601 strings to DateTime and other strings to String", () => {
    const { apex } = generateApexClasses(
      JSON.stringify({
        instant: "2026-10-27T09:15:00Z",
        dateOnly: "2026-12-31",
        notADate: "next tuesday",
      }),
    );
    expect(apex).toContain("public DateTime instant { get; set; }");
    expect(apex).toContain("public DateTime dateOnly { get; set; }");
    expect(apex).toContain("public String notADate { get; set; }");
  });

  it("folds nulls into String members", () => {
    const { apex } = generateApexClasses('{"refunded": null}');
    expect(apex).toContain("public String refunded { get; set; }");
  });

  it("maps booleans and generates List<T> for scalar arrays", () => {
    const { apex } = generateApexClasses(
      JSON.stringify({ isDeleted: false, tags: ["a", "b"], scores: [1, 2.5] }),
    );
    expect(apex).toContain("public Boolean isDeleted { get; set; }");
    expect(apex).toContain("public List<String> tags { get; set; }");
    expect(apex).toContain("public List<Decimal> scores { get; set; }");
  });

  it("degrades heterogeneous arrays to List<Object> without inner classes", () => {
    const result = generateApexClasses(
      JSON.stringify({ mixed: [{ a: 1 }, "str", 3] }),
    );
    expect(result.apex).toContain("public List<Object> mixed { get; set; }");
    expect(result.innerClassCount).toBe(0);
  });

  it("types arrays of null-and-scalar as the scalar's list type", () => {
    const { apex } = generateApexClasses(
      JSON.stringify({ maybe: ["x", null, "y"] }),
    );
    expect(apex).toContain("public List<String> maybe { get; set; }");
  });

  it("maps empty arrays to List<Object>", () => {
    const { apex } = generateApexClasses('{"empty": []}');
    expect(apex).toContain("public List<Object> empty { get; set; }");
  });

  it("supports nested arrays including arrays of objects", () => {
    const result = generateApexClasses(
      JSON.stringify({ matrix: [[1, 2], [3]], groups: [[{ name: "a" }]] }),
    );
    expect(result.apex).toContain(
      "public List<List<Decimal>> matrix { get; set; }",
    );
    expect(result.apex).toContain("public List<List<Groups>> groups");
    expect(result.innerClassCount).toBe(1);
  });
});

describe("apex class structure", () => {
  it("emits a byte-identical golden class for a nested payload (hub preset)", () => {
    const result = generateApexClasses(
      JSON.stringify({ done: true, account: { Name: "Acme" } }),
    );
    expect(result.apex).toBe(
      expectCls([
        "public class JsonResponse {",
        "    @AuraEnabled",
        "    public Boolean done { get; set; }",
        "",
        "    @AuraEnabled",
        "    public Account account { get; set; }",
        "",
        "    public class Account {",
        "        @AuraEnabled",
        "        public String Name { get; set; }",
        "    }",
        "",
        "    @AuraEnabled",
        "    public static JsonResponse parse(String json) {",
        "        return (JsonResponse) JSON.deserialize(json, JsonResponse.class);",
        "    }",
        "",
        "    @AuraEnabled",
        "    public String serialize() {",
        "        return JSON.serialize(this);",
        "    }",
        "}",
      ]),
    );
    expect(result.className).toBe("JsonResponse");
    expect(result.innerClassCount).toBe(1);
  });

  it("preserves deep nesting through four object levels", () => {
    const result = generateApexClasses(
      JSON.stringify({
        l1: { l2: { l3: { l4: { leaf: "value" } } } },
      }),
    );
    expect(result.innerClassCount).toBe(4);
    expect(result.apex).toContain("public class L4 {");
    expect(result.apex).toContain("public String leaf { get; set; }");
    // Inner classes nest inside their parents (increasing indentation).
    expect(result.apex.indexOf("public class L1 {")).toBeLessThan(
      result.apex.indexOf("public class L4 {"),
    );
  });

  it("merges array items into one inner class with the union of fields", () => {
    const result = generateApexClasses(
      JSON.stringify({
        records: [
          { Id: "001", Name: "Acme" },
          { Id: "002", Industry: "Energy" },
        ],
      }),
    );
    expect(result.innerClassCount).toBe(1);
    expect(result.apex).toContain("public List<Records> records { get; set; }");
    expect(result.apex).toContain("public String Id { get; set; }");
    expect(result.apex).toContain("public String Name { get; set; }");
    expect(result.apex).toContain("public String Industry { get; set; }");
  });

  it("keeps same-named members distinct when keys mangle to the same name", () => {
    const result = generateApexClasses(
      JSON.stringify({ class: 1, ClassX: 2 }),
    );
    expect(result.apex).toContain("public Decimal ClassX { get; set; }");
    expect(result.apex).toContain("public Decimal ClassX2 { get; set; }");
  });

  it("sanitizes the root class name", () => {
    const { className } = generateApexClasses('{"a": 1}', {
      rootName: "my wrapper class",
    });
    expect(className).toBe("MyWrapperClass");
  });

  it("defaults the root name to JsonResponse", () => {
    const { className } = generateApexClasses('{"a": 1}');
    expect(className).toBe("JsonResponse");
  });

  it("emits an empty class body with only helpers for an empty object", () => {
    const result = generateApexClasses("{}");
    expect(result.apex).toBe(
      expectCls([
        "public class JsonResponse {",
        "    @AuraEnabled",
        "    public static JsonResponse parse(String json) {",
        "        return (JsonResponse) JSON.deserialize(json, JsonResponse.class);",
        "    }",
        "",
        "    @AuraEnabled",
        "    public String serialize() {",
        "        return JSON.serialize(this);",
        "    }",
        "}",
      ]),
    );
    expect(result.innerClassCount).toBe(0);
  });
});

describe("apex root arrays", () => {
  it("returns List<Root> from parse() for a top-level array of objects", () => {
    const result = generateApexClasses('[{"Id": "001"}, {"Id": "002"}]');
    expect(result.apex).toContain(
      "public static List<JsonResponse> parse(String json) {",
    );
    expect(result.apex).toContain(
      "return (List<JsonResponse>) JSON.deserialize(json, List<JsonResponse>.class);",
    );
    expect(result.apex).toContain("public String Id { get; set; }");
  });

  it("uses the object variant when array items merge objects with nulls", () => {
    const result = generateApexClasses('[{"a": 1}, null]');
    expect(result.apex).toContain("public Decimal a { get; set; }");
    expect(result.apex).toContain("List<JsonResponse> parse");
  });
});

describe("apex generation options", () => {
  const input = JSON.stringify({ done: true });

  it("omits annotations and helpers when everything is off", () => {
    const result = generateApexClasses(input, {
      auraEnabled: false,
      includeParse: false,
      includeSerialize: false,
    });
    expect(result.apex).toBe(
      expectCls([
        "public class JsonResponse {",
        "    public Boolean done { get; set; }",
        "}",
      ]),
    );
    expect(result.apex).not.toContain("@AuraEnabled");
    expect(result.apex).not.toContain("parse");
    expect(result.apex).not.toContain("serialize");
  });

  it("omits @AuraEnabled from members and methods with the wrapper preset", () => {
    const result = generateApexClasses(input, APEX_PRESETS.wrapper);
    expect(result.apex).not.toContain("@AuraEnabled");
    expect(result.apex).toContain("public static JsonResponse parse(");
    expect(result.apex).toContain("public String serialize() {");
  });

  it("omits serialize() with the lwc preset but keeps @AuraEnabled and parse()", () => {
    const result = generateApexClasses(input, APEX_PRESETS.lwc);
    expect(result.apex).toContain("@AuraEnabled");
    expect(result.apex).toContain("public static JsonResponse parse(");
    expect(result.apex).not.toContain("public String serialize()");
  });

  it("annotates parse() and serialize() when @AuraEnabled is on", () => {
    const result = generateApexClasses(input, APEX_PRESETS.hub);
    expect(result.apex).toContain("    @AuraEnabled\n    public static JsonResponse parse(");
    expect(result.apex).toContain("    @AuraEnabled\n    public String serialize()");
  });
});

describe("apex error handling", () => {
  it("throws a descriptive error for empty input", () => {
    expect(() => generateApexClasses("")).toThrow(
      /appears to be empty/,
    );
    expect(() => generateApexClasses("   \n\t ")).toThrow(
      ApexGenerationError,
    );
  });

  it("throws for scalar roots", () => {
    expect(() => generateApexClasses("42")).toThrow(
      /root JSON value must be an object or an array of objects/,
    );
    expect(() => generateApexClasses('"just a string"')).toThrow(
      ApexGenerationError,
    );
    expect(() => generateApexClasses("null")).toThrow(ApexGenerationError);
    expect(() => generateApexClasses("true")).toThrow(ApexGenerationError);
  });

  it("throws for arrays without objects", () => {
    expect(() => generateApexClasses("[]")).toThrow(/empty array/);
    expect(() => generateApexClasses("[1, 2, 3]")).toThrow(
      /contains no objects/,
    );
    expect(() => generateApexClasses('["a", "b"]')).toThrow(
      /contains no objects/,
    );
  });

  it("wraps JSON syntax errors with the parser's message", () => {
    expect(() => generateApexClasses("{ not json")).toThrow(
      /Unable to parse JSON input/,
    );
  });

  it("propagates the nesting-depth limit", () => {
    let deep: unknown = { leaf: 1 };
    for (let i = 0; i < 40; i++) {
      deep = { nested: deep };
    }
    expect(() => generateApexClasses(JSON.stringify(deep))).toThrow(
      /maximum supported nesting depth of 32/,
    );
  });
});

describe("apex differentiation options", () => {
  const input = JSON.stringify({ done: true });

  it("emits parse() as @AuraEnabled(cacheable=true) with cacheableParse", () => {
    const { apex } = generateApexClasses(input, { cacheableParse: true });
    expect(apex).toContain(
      "    @AuraEnabled(cacheable=true)\n    public static JsonResponse parse(String json) {",
    );
    // The cacheable annotation replaces the plain one — never both.
    expect(apex).not.toContain(
      "    @AuraEnabled\n    public static JsonResponse parse",
    );
  });

  it("skips the cacheable annotation when parse() is off", () => {
    const { apex } = generateApexClasses(input, {
      cacheableParse: true,
      includeParse: false,
    });
    expect(apex).not.toContain("cacheable");
    expect(apex).not.toContain("parse");
  });

  it("emits fromHttpResponse(HttpResponse) with includeCalloutHelper", () => {
    const { apex } = generateApexClasses(input, { includeCalloutHelper: true });
    expect(apex).toContain(
      "    public static JsonResponse fromHttpResponse(HttpResponse response) {",
    );
    expect(apex).toContain("        return parse(response.getBody());");
  });

  it("types the callout helper as List<T> for root arrays", () => {
    const { apex } = generateApexClasses('[{"a": 1}]', {
      includeCalloutHelper: true,
    });
    expect(apex).toContain(
      "    public static List<JsonResponse> fromHttpResponse(HttpResponse response) {",
    );
  });

  it("skips the callout helper when parse() is off", () => {
    const { apex } = generateApexClasses(input, {
      includeCalloutHelper: true,
      includeParse: false,
    });
    expect(apex).not.toContain("fromHttpResponse");
  });

  it("lwc preset ships a cacheable, wire-callable parse() without serialize()", () => {
    const { apex } = generateApexClasses(input, APEX_PRESETS.lwc);
    expect(apex).toContain("@AuraEnabled(cacheable=true)");
    expect(apex).not.toContain("public String serialize()");
  });

  it("wrapper preset ships the callout helper plus both round-trip helpers", () => {
    const { apex } = generateApexClasses(input, APEX_PRESETS.wrapper);
    expect(apex).toContain("fromHttpResponse(HttpResponse response)");
    expect(apex).toContain("public String serialize()");
    expect(apex).not.toContain("@AuraEnabled");
  });
});

describe("apex determinism", () => {
  it("produces byte-identical output across runs", () => {
    const raw = JSON.stringify({
      b: 2,
      a: { x: [1, { y: null }], z: "2026-01-01" },
    });
    const first = generateApexClasses(raw);
    const second = generateApexClasses(raw);
    expect(second.apex).toBe(first.apex);
    expect(second.innerClassCount).toBe(first.innerClassCount);
  });
});

describe("apex UI sample payloads", () => {
  it("generates the SOQL query-result class with merged optional fields", () => {
    const soql = JSON.stringify({
      totalSize: 2,
      done: true,
      nextRecordsUrl: "/services/data/v60.0/query/01gXX/",
      records: [
        {
          attributes: {
            type: "Account",
            url: "/services/data/v60.0/sobjects/Account/001XX/",
          },
          Id: "001XX000003DGb2AAG",
          Name: "Acme Corp",
          AnnualRevenue: 1250000.5,
          LastActivityDate: "2026-09-30",
          IsDeleted: false,
        },
        {
          attributes: {
            type: "Account",
            url: "/services/data/v60.0/sobjects/Account/001YY/",
          },
          Id: "001XX000003DGb3AAG",
          Name: "Globex",
          AnnualRevenue: 99000,
          Industry: "Energy",
        },
      ],
    });
    const result = generateApexClasses(soql, APEX_PRESETS.hub);

    expect(result.className).toBe("JsonResponse");
    expect(result.innerClassCount).toBe(2);
    expect(result.apex).toContain(
      "public List<Records> records { get; set; }",
    );
    expect(result.apex).toContain("public class Records {");
    expect(result.apex).toContain("public class Attributes {");
    // `type` is an official Apex reserved keyword → mangled. That field
    // will not auto-map and needs a manual assignment — unavoidable, and
    // still compiles.
    expect(result.apex).toContain("public String TypeX { get; set; }");
    // `url` is only a system class name — legal as a member, so the JSON
    // key keeps deserializing.
    expect(result.apex).toContain("public String url { get; set; }");
    expect(result.apex).toContain("public Decimal AnnualRevenue { get; set; }");
    expect(result.apex).toContain(
      "public DateTime LastActivityDate { get; set; }",
    );
    expect(result.apex).toContain("public Boolean IsDeleted { get; set; }");
    // Present on only one record — still a member so every item deserializes.
    expect(result.apex).toContain("public String Industry { get; set; }");
  });

  it("generates the LWC wire-response class without serialize()", () => {
    const wire = JSON.stringify({
      opportunity: {
        Id: "006XX000004dDaaGAE",
        Name: "Renewal — Acme Corp",
        Amount: 48000,
        StageName: "Proposal",
        CloseDate: "2026-12-31",
        IsWon: false,
      },
      lineItems: [
        { product: "Sales Cloud", quantity: 12, unitPrice: 4000, isRenewal: true },
        { product: "Service Cloud", quantity: 4, unitPrice: 600.5 },
      ],
      computedAt: "2026-10-27T09:15:00Z",
    });
    const result = generateApexClasses(wire, {
      ...APEX_PRESETS.lwc,
      rootName: "LwcResponse",
    });

    expect(result.className).toBe("LwcResponse");
    expect(result.innerClassCount).toBe(2);
    expect(result.apex).toContain(
      "public Opportunity opportunity { get; set; }",
    );
    expect(result.apex).toContain(
      "public List<LineItems> lineItems { get; set; }",
    );
    expect(result.apex).toContain("public Decimal unitPrice { get; set; }");
    expect(result.apex).toContain("public DateTime CloseDate { get; set; }");
    expect(result.apex).toContain("public DateTime computedAt { get; set; }");
    // LWC preset: cacheable, wire-callable parse(), no serialize().
    expect(result.apex).toContain("public static LwcResponse parse(String json) {");
    expect(result.apex).toContain("    @AuraEnabled(cacheable=true)");
    expect(result.apex).not.toContain("public String serialize()");
  });

  it("generates the REST callout wrapper with plain members and both helpers", () => {
    const callout = JSON.stringify({
      status: "success",
      requestId: "req_9f2c81",
      payment: {
        id: "pay_3Xb2",
        amount: 1999.99,
        currency: "usd",
        captured: true,
        refunded: null,
      },
      metadata: { orderId: "a-1023", source: "web" },
    });
    const result = generateApexClasses(callout, {
      ...APEX_PRESETS.wrapper,
      rootName: "CalloutWrapper",
    });

    expect(result.className).toBe("CalloutWrapper");
    expect(result.innerClassCount).toBe(2);
    expect(result.apex).not.toContain("@AuraEnabled");
    expect(result.apex).toContain("public Payment payment { get; set; }");
    expect(result.apex).toContain("public Decimal amount { get; set; }");
    expect(result.apex).toContain("public String refunded { get; set; }");
    expect(result.apex).toContain(
      "public static CalloutWrapper parse(String json) {",
    );
    expect(result.apex).toContain("public String serialize() {");
    expect(result.apex).toContain("return JSON.serialize(this);");
    // The wrapper preset's differentiator: one-line callout-body parsing.
    expect(result.apex).toContain(
      "    public static CalloutWrapper fromHttpResponse(HttpResponse response) {",
    );
  });
});
